/**
 * PixiOverlay - Floating DOM panel for editing block parameters in Pixi mode.
 *
 * When a block is selected in PixiWorkspaceRenderer, this panel appears
 * near the block and shows the full parameter editing controls generated by
 * BlockRenderer. Input changes flow through BlockSystem.updateBlockFromDOM
 * and StorageManager.autoSave exactly as in DOM mode.
 */
const PixiOverlay = {
    _el: null,
    _contentEl: null,
    _currentBlockId: null,

    _build() {
        if (this._el) return;

        const el = document.createElement('div');
        el.id = 'pixi-block-overlay';
        el.setAttribute('role', 'dialog');
        el.setAttribute('aria-label', 'Block parameters');
        el.style.cssText = [
            'position:fixed',
            'z-index:1200',
            'min-width:180px',
            'max-width:290px',
            'max-height:70vh',
            'overflow-y:auto',
            'background:var(--card-bg,#1e1e2e)',
            'border:2px solid var(--border,#333)',
            'border-radius:8px',
            'padding:10px 14px 14px',
            'box-shadow:0 8px 32px rgba(0,0,0,.6)',
            'font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace',
            'font-size:11px',
            'color:#e2e8f0',
            'display:none',
            'pointer-events:auto',
        ].join(';');

        // Close button (top-right)
        const closeBtn = document.createElement('button');
        closeBtn.textContent = '×';
        closeBtn.title = 'Close';
        closeBtn.style.cssText = 'position:absolute;top:6px;right:8px;background:none;border:none;color:#666;font-size:18px;line-height:1;cursor:pointer;padding:0';
        closeBtn.addEventListener('click', () => this.hide());
        el.appendChild(closeBtn);

        // Content area
        const content = document.createElement('div');
        content.className = 'pixi-overlay-content';
        el.appendChild(content);

        document.body.appendChild(el);
        this._el = el;
        this._contentEl = content;

        // Keep overlay from closing when user clicks inside it
        el.addEventListener('pointerdown', e => e.stopPropagation());
    },

    show(blockData, renderer) {
        this._build();
        this._currentBlockId = blockData.id;

        const content = this._contentEl;
        content.innerHTML = '';

        if (typeof BlockRenderer === 'undefined') {
            content.textContent = '(BlockRenderer unavailable)';
        } else {
            // Create a stand-in element with the same dataset that BlockRenderer expects
            const mockEl = document.createElement('div');
            mockEl.dataset.blockId = String(blockData.id);
            mockEl.dataset.type = blockData.type;
            if (blockData.motor_id !== undefined) mockEl.dataset.motorId = String(blockData.motor_id);
            if (blockData.relay_id !== undefined) mockEl.dataset.relayId = String(blockData.relay_id);
            if (blockData.keyCode)  mockEl.dataset.keyCode = blockData.keyCode;

            mockEl.innerHTML = BlockRenderer.generateScratchBlockContent(blockData);

            // Wire up live-update listeners via the existing mechanism
            BlockRenderer.attachParameterListeners(mockEl, blockData);

            // After any param change, also refresh the Pixi label
            mockEl.addEventListener('input', () => {
                const latest = WorkflowManager.blocks.get(blockData.id);
                if (latest && typeof PixiWorkspaceRenderer !== 'undefined' && PixiWorkspaceRenderer.enabled) {
                    PixiWorkspaceRenderer.updateBlock(latest);
                }
            });
            mockEl.addEventListener('change', () => {
                const latest = WorkflowManager.blocks.get(blockData.id);
                if (latest && typeof PixiWorkspaceRenderer !== 'undefined' && PixiWorkspaceRenderer.enabled) {
                    PixiWorkspaceRenderer.updateBlock(latest);
                }
            });

            content.appendChild(mockEl);
        }

        // Delete button
        const del = document.createElement('button');
        del.textContent = 'Delete Block';
        del.style.cssText = 'margin-top:10px;width:100%;padding:4px 8px;font-size:10px;background:#7f1d1d;color:#fff;border:none;border-radius:4px;cursor:pointer;';
        del.addEventListener('click', () => {
            if (typeof UIUtils !== 'undefined') {
                if (!UIUtils.confirm(`Delete block ${blockData.id}?`)) return;
            }
            WorkflowManager.removeBlock(blockData.id);
            this.hide();
        });
        this._contentEl.appendChild(del);

        this._el.style.display = 'block';
        this.reposition(blockData, renderer);
    },

    reposition(blockData, renderer) {
        if (!this._el || this._currentBlockId !== blockData.id) return;
        const r = renderer || (typeof PixiWorkspaceRenderer !== 'undefined' ? PixiWorkspaceRenderer : null);
        if (!r) return;
        const pos = r.getBlockScreenPos(blockData.id);
        if (!pos) return;

        const vw = window.innerWidth;
        const vh = window.innerHeight;
        const elW = 290;
        const elH = Math.min(parseInt(this._el.style.maxHeight, 10) || 400, vh * 0.7);

        // Prefer right of block, flip left if off-screen
        let left = pos.x + pos.w + 10;
        if (left + elW > vw - 8) left = pos.x - elW - 10;
        if (left < 8) left = 8;

        let top = pos.y;
        if (top + elH > vh - 8) top = vh - elH - 8;
        if (top < 8) top = 8;

        this._el.style.left = left + 'px';
        this._el.style.top  = top  + 'px';
    },

    hide() {
        if (this._el) this._el.style.display = 'none';
        this._currentBlockId = null;
    },

    isVisible() {
        return !!this._el && this._el.style.display !== 'none';
    },

    currentBlockId() {
        return this._currentBlockId;
    },
};
